const MONTH_NAMES_KR = ['1월', '2월', '3월', '4월', '5월', '6월', '7월', '8월', '9월', '10월', '11월', '12월'];

const SUM_FIELDS = [
  'gmv', 'orders', 'customers', 'itemsSold', 'itemsCanceledReturned', 'itemsRefunded', 'skuOrders',
  'liveGmv', 'videoGmv', 'productCardGmv', 'gmvWithTax', 'tax', 'shippingFees',
  'productImpressions', 'uniqueProductImpressions', 'productClicks', 'uniqueClicks',
];

function sumRecords(records) {
  const sums = records.reduce((acc, r) => {
    SUM_FIELDS.forEach((f) => { acc[f] += r[f]; });
    return acc;
  }, Object.fromEntries(SUM_FIELDS.map((f) => [f, 0])));
  sums.aov = sums.orders ? Math.round((sums.gmv / sums.orders) * 100) / 100 : 0;
  sums.ctr = sums.productImpressions ? Math.round((sums.productClicks / sums.productImpressions) * 1000) / 10 : 0;
  sums.refundRate = sums.itemsSold ? Math.round((sums.itemsCanceledReturned / sums.itemsSold) * 1000) / 10 : 0;
  return sums;
}

export function aggregateRange(daily, startDate, endDate) {
  return sumRecords(daily.filter((d) => d.date >= startDate && d.date <= endDate));
}

export function groupMonths(daily) {
  const map = new Map();
  daily.forEach((r) => {
    const key = r.date.slice(0, 7);
    if (!map.has(key)) map.set(key, []);
    map.get(key).push(r);
  });
  return [...map.entries()].map(([key, records]) => {
    const [year, month] = key.split('-').map(Number);
    return {
      key,
      label: `${String(year).slice(2)}.${String(month).padStart(2, '0')}`,
      monthName: MONTH_NAMES_KR[month - 1],
      year,
      ...sumRecords(records),
      activeDays: records.filter((r) => r.gmv > 0).length,
      totalDays: records.length,
    };
  });
}

export const monthlyAnalytics = groupMonths(dailyAnalytics);
export const overallAnalytics = aggregateRange(dailyAnalytics, dailyAnalytics[0].date, dailyAnalytics[dailyAnalytics.length - 1].date);
export const firstDate = dailyAnalytics[0].date;
export const lastDate = dailyAnalytics[dailyAnalytics.length - 1].date;

export const topSpikeDays = [...dailyAnalytics]
  .sort((a, b) => b.gmv - a.gmv)
  .map(({ date, gmv, orders, customers }) => ({ date, gmv, orders, customers }));
